def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'D'
    if n == 2:
        return 'C'

    my = [h[0] for h in history]
    opp = [h[1] for h in history]
    opp_defects = sum(1 for a in opp if a == 'D')
    opp_coops = n - opp_defects
    my_last = my[-1]
    opp_last = opp[-1]

    # Exploit unconditional cooperators
    if opp_defects == 0:
        return 'D'

    # Defect against always defectors
    if opp_coops == 0:
        return 'D'

    # Endgame: defect on the last round if opponent has cooperated
    if n == 99 and opp_coops > 0:
        return 'D'

    # Forgiving Tit-for-Tat with limited forgiveness
    if opp_last == 'C':
        return 'C'
    else:
        if my_last == 'C':
            consec_cd = 0
            for i in range(n - 1, -1, -1):
                if my[i] == 'C' and opp[i] == 'D':
                    consec_cd += 1
                else:
                    break
            if consec_cd >= 4:
                return 'D'
            return 'C'
        else:
            consec_my_d = 0
            for a in reversed(my):
                if a == 'D':
                    consec_my_d += 1
                else:
                    break
            if consec_my_d >= 2 and opp_coops > 0:
                if rng.random() < 0.5:
                    return 'C'
            return 'D'
